package com.goodlife.app.i18n

// Fichier généré : dictionnaire français → anglais utilisé par t(). Une entrée = « français \u0001 anglais ».

internal val EN: Map<String, String> by lazy {
    val m = HashMap<String, String>(5020)
    listOf(P0, P1, P2, P3, P4, P5, P6, P7, P8, P9, P10, P11).forEach { part ->
        part.split('\u0002').forEach { e -> val i = e.indexOf('\u0001'); if (i > 0) m[e.substring(0, i)] = e.substring(i + 1) }
    }
    m
}

